import { PrismaClient } from "@prisma/client";

/**
 * E2E helpers that talk directly to the seeded database. Tracking numbers are
 * randomly generated by the seed, so tests look up a real one instead of
 * hard-coding it. These run in Playwright's Node context (not the browser).
 */

let cached: PrismaClient | null = null;
function prisma(): PrismaClient {
  if (!cached) cached = new PrismaClient();
  return cached;
}

export interface SeededShipment {
  trackingNumber: string;
  recipientStreet: string;
  recipientPhone: string;
  recipientName: string;
  recipientCity: string;
}

/** Returns a DELIVERED shipment plus its recipient PII (to assert masking). */
export async function findDeliveredShipment(): Promise<SeededShipment> {
  const shipment = await prisma().shipment.findFirst({
    where: { status: "DELIVERED" },
    include: { recipientAddress: true },
    orderBy: { createdAt: "asc" },
  });
  if (!shipment || !shipment.recipientAddress) {
    throw new Error("No DELIVERED seed shipment found — run `npm run db:seed`.");
  }
  const a = shipment.recipientAddress;
  return {
    trackingNumber: shipment.trackingNumber,
    recipientStreet: a.line1,
    recipientPhone: a.phone ?? "",
    recipientName: a.contactName,
    recipientCity: a.city,
  };
}

/** Returns the id of a shipment currently in the given status (for ops tests). */
export async function findShipmentIdByStatus(status: "CREATED" | "CONFIRMED" | "DELIVERED"): Promise<string> {
  const s = await prisma().shipment.findFirst({ where: { status }, orderBy: { createdAt: "asc" }, select: { id: true } });
  if (!s) throw new Error(`No seed shipment in status ${status} — run \`npm run db:seed\`.`);
  return s.id;
}

export async function closePrisma(): Promise<void> {
  if (cached) {
    await cached.$disconnect();
    cached = null;
  }
}
